using System;
using System.IO;
using System.Drawing;
internal static class SongesOcrAcceptance {
 internal static int Run(string folder){try{var engine=new SongesOcr();using(var start=new Bitmap(Path.Combine(folder,"start.png")))using(var win=new Bitmap(Path.Combine(folder,"victory.png")))using(var waves=new Bitmap(Path.Combine(folder,"waves.png")))using(var blank=new Bitmap(2048,1217)){var a=engine.Read(start).GetAwaiter().GetResult();var b=engine.Read(win).GetAwaiter().GetResult();var c=engine.Read(blank).GetAwaiter().GetResult();var w=engine.Read(waves).GetAwaiter().GetResult();if(!a.EndTurn||a.Victory||!b.Victory||b.EndTurn||c.EndTurn||c.Victory||a.Depth!=5||b.Depth!=9||!w.EndTurn||w.Victory||w.Depth!=26)throw new Exception("Reconnaissance des repères fournis : start="+a.EndTurn+" depth="+a.Depth+" victory="+b.Victory+" depth="+b.Depth+" TOP_START="+a.DepthText+" TOP_END="+b.DepthText+" WAVES="+w.EndTurn+" DEPTH="+w.Depth+" TEXT="+w.DepthText);File.WriteAllText(Path.Combine(folder,"SONGES_OCR_PASS.txt"),"PASS: actual user-provided FIN DE TOUR glyphs, yellow VICTOIRE banner and depth labels, on neutral test frames. Wave battle depth 26 and FIN DE TOUR, with the non-result wave heading ignored. Blank negative frame. Live capture on user's game still needs verification.");}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"SONGES_OCR_FAIL.txt"),ex.ToString());return 1;}}
}
